mapper.select:
SELECT 
FROM HR_ANNIVERSARY A
LEFT JOIN APP_USER U ON U.USER_ID = A.USER_ID


		AND SUBSTRING(A.ANNIV_DE, 1, 2) = #{month}


		AND A.USE_YN = #{useYn}


		AND (A.TITLE LIKE '%' || #{searchKeyword} || '%'
			OR A.USER_ID LIKE '%' || #{searchKeyword} || '%'
			OR U.USER_NM LIKE '%' || #{searchKeyword} || '%')


ORDER BY A.ANNIV_DE, U.USER_NM, A.ANNIV_ID
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) FROM HR_ANNIVERSARY A LEFT JOIN APP_USER U ON U.USER_ID = A.USER_ID
AND SUBSTRING(A.ANNIV_DE, 1, 2) = #{month}
AND A.USE_YN = #{useYn}
AND (A.TITLE LIKE '%' || #{searchKeyword} || '%' OR A.USER_ID LIKE '%' || #{searchKeyword} || '%' OR U.USER_NM LIKE '%' || #{searchKeyword} || '%')

mapper.insert:
INSERT INTO HR_ANNIVERSARY (
	ANNIV_ID, USER_ID, ANNIV_TYPE, ANNIV_DE, TITLE, REMARK, USE_YN, REGIST_DT
) VALUES (
	#{annivId}, #{userId}, #{annivType}, #{annivDe}, #{title}, #{remark}, #{useYn}, CURRENT_TIMESTAMP
)

mapper.select:
SELECT FROM HR_EVENT E LEFT JOIN APP_USER U ON U.USER_ID = E.USER_ID
AND E.EVENT_DE LIKE #{year} || '%'
AND E.EVENT_TYPE = #{eventType}
AND (E.TITLE LIKE '%' || #{searchKeyword} || '%' OR E.USER_ID LIKE '%' || #{searchKeyword} || '%' OR U.USER_NM LIKE '%' || #{searchKeyword} || '%')
ORDER BY E.EVENT_DE DESC, E.EVENT_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO HR_EVENT (
	EVENT_ID, USER_ID, EVENT_TYPE, EVENT_DE, TITLE, AMOUNT, REMARK, REGIST_DT
) VALUES (
	#{eventId}, #{userId}, #{eventType}, #{eventDe}, #{title}, #{amount}, #{remark}, CURRENT_TIMESTAMP
)

mapper.select:
SELECT FROM HR_REWARD R LEFT JOIN APP_USER U ON U.USER_ID = R.USER_ID
AND R.REWARD_DE LIKE #{year} || '%'
AND R.REWARD_TYPE = #{rewardType}
AND (R.TITLE LIKE '%' || #{searchKeyword} || '%' OR R.USER_ID LIKE '%' || #{searchKeyword} || '%' OR U.USER_NM LIKE '%' || #{searchKeyword} || '%' OR R.REWARDER LIKE '%' || #{searchKeyword} || '%')
ORDER BY R.REWARD_DE DESC, R.REWARD_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO HR_REWARD (
	REWARD_ID, USER_ID, REWARD_TYPE, REWARD_DE, TITLE, AMOUNT, REWARDER, REMARK, REGIST_DT
) VALUES (
	#{rewardId}, #{userId}, #{rewardType}, #{rewardDe}, #{title}, #{amount}, #{rewarder}, #{remark}, CURRENT_TIMESTAMP
)
